-- TaskEsc schema 30 (agenda WhatsApp; schema 20 retirado) | MySQL 8+ / MariaDB 10.6+ | UTF-8
SET NAMES utf8mb4;
SET time_zone = '+00:00';
CREATE TABLE IF NOT EXISTS settings (`key` VARCHAR(100) PRIMARY KEY, value LONGTEXT NOT NULL) ENGINE=InnoDB;
-- Schema 21: Outbox transacional. Schema 20 permanece reservado ao SaaS removido.
-- DDL idempotente. Migrations::outbox() valida a estrutura antes de avançar o marcador.
-- Não executar DDL dentro de uma transação de negócio (MySQL faz commit implícito).
CREATE TABLE IF NOT EXISTS event_outbox (
 id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
 event_key CHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
 event_hash CHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
 event_type VARCHAR(100) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
 entity_type VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
 entity_id BIGINT UNSIGNED NOT NULL,
 channel VARCHAR(190) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
 payload_json JSON NOT NULL,
 created_by INT NULL,
 created_at DATETIME(6) NOT NULL,
 available_at DATETIME(6) NOT NULL,
 published_at DATETIME(6) NULL,
 attempts INT UNSIGNED NOT NULL DEFAULT 0,
 last_error VARCHAR(80) CHARACTER SET ascii COLLATE ascii_bin NULL,
 PRIMARY KEY (id),
 UNIQUE KEY uq_event_outbox_event_key (event_key),
 KEY idx_event_outbox_ready (published_at,available_at,id),
 KEY idx_event_outbox_entity (entity_type,entity_id,id),
 KEY idx_event_outbox_published (published_at,id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

CREATE TABLE users (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(150) NOT NULL, email VARCHAR(190) NOT NULL UNIQUE, whatsapp_phone VARCHAR(20) NULL, ai_assistant_enabled TINYINT NOT NULL DEFAULT 0, password_hash VARCHAR(255) NOT NULL, role VARCHAR(20) NOT NULL DEFAULT 'client', active TINYINT NOT NULL DEFAULT 1, email_notifications TINYINT NOT NULL DEFAULT 1, weekly_report TINYINT NOT NULL DEFAULT 0, twofa_secret VARCHAR(190) NULL, twofa_enabled TINYINT NOT NULL DEFAULT 0, twofa_recovery_json TEXT NULL, last_login_at DATETIME NULL, last_login_ip VARCHAR(45) NULL, created_at DATETIME NOT NULL) ENGINE=InnoDB;
-- B1.1: estruturas aditivas multiempresa. Bootstrap de vínculos EXPLÍCITO via migração 031.
CREATE TABLE IF NOT EXISTS accounts (
 id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
 slug VARCHAR(100) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
 name VARCHAR(190) NOT NULL,
 account_type VARCHAR(20) NOT NULL DEFAULT 'customer',
 status VARCHAR(20) NOT NULL DEFAULT 'active',
 created_at DATETIME NOT NULL,
 updated_at DATETIME NOT NULL,
 PRIMARY KEY (id),
 UNIQUE KEY uq_accounts_slug (slug),
 KEY idx_accounts_status (status,id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE IF NOT EXISTS account_members (
 account_id BIGINT UNSIGNED NOT NULL,
 user_id INT NOT NULL,
 membership_role VARCHAR(20) NOT NULL DEFAULT 'member',
 status VARCHAR(20) NOT NULL DEFAULT 'active',
 joined_at DATETIME NOT NULL,
 PRIMARY KEY (account_id,user_id),
 KEY idx_account_members_user (user_id,status,account_id),
 CONSTRAINT fk_account_members_account FOREIGN KEY (account_id) REFERENCES accounts(id) ON DELETE RESTRICT,
 CONSTRAINT fk_account_members_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE IF NOT EXISTS account_settings (
 account_id BIGINT UNSIGNED NOT NULL,
 `key` VARCHAR(100) NOT NULL,
 value LONGTEXT NOT NULL,
 updated_at DATETIME NOT NULL,
 PRIMARY KEY (account_id,`key`),
 CONSTRAINT fk_account_settings_account FOREIGN KEY (account_id) REFERENCES accounts(id) ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
CREATE TABLE clients (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(190) NOT NULL, brand VARCHAR(190) NOT NULL DEFAULT '', commercial_type VARCHAR(20) NOT NULL DEFAULT 'one_off', monthly_amount_cents BIGINT NOT NULL DEFAULT 0, monthly_payment_day TINYINT UNSIGNED NOT NULL DEFAULT 10, drive_account_id INT NULL, drive_folder_id VARCHAR(255) NULL, email VARCHAR(190) NOT NULL DEFAULT '', phone VARCHAR(60) NOT NULL DEFAULT '', whatsapp_phone VARCHAR(20) NULL, document VARCHAR(40) NOT NULL DEFAULT '', notes TEXT, brand_url TEXT, active TINYINT NOT NULL DEFAULT 1, created_at DATETIME NOT NULL, INDEX(drive_account_id), tenant_account_id BIGINT UNSIGNED NULL, KEY idx_saas_clients (tenant_account_id,id)) ENGINE=InnoDB;
CREATE TABLE user_clients (user_id INT NOT NULL, client_id INT NOT NULL, can_approve TINYINT NOT NULL DEFAULT 1, can_finance TINYINT NOT NULL DEFAULT 0, PRIMARY KEY(user_id,client_id), FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(client_id) REFERENCES clients(id)) ENGINE=InnoDB;
CREATE TABLE stages (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(80) NOT NULL, kind VARCHAR(20) NOT NULL, color VARCHAR(7) NOT NULL DEFAULT '#737373', position INT NOT NULL DEFAULT 0, active TINYINT NOT NULL DEFAULT 1, tenant_account_id BIGINT UNSIGNED NULL, KEY idx_saas_stages (tenant_account_id,id)) ENGINE=InnoDB;
CREATE TABLE categories (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(80) NOT NULL, fields_json TEXT NOT NULL, default_amount_cents BIGINT NOT NULL DEFAULT 0, default_due_hours INT NOT NULL DEFAULT 24, default_revisions INT NOT NULL DEFAULT 2, default_priority VARCHAR(20) NOT NULL DEFAULT 'normal', default_assigned_to INT NULL, checklist_json TEXT NULL, active TINYINT NOT NULL DEFAULT 1, INDEX(default_assigned_to), FOREIGN KEY(default_assigned_to) REFERENCES users(id), tenant_account_id BIGINT UNSIGNED NULL, KEY idx_saas_categories (tenant_account_id,id)) ENGINE=InnoDB;
CREATE TABLE projects (id INT AUTO_INCREMENT PRIMARY KEY, client_id INT NOT NULL, name VARCHAR(190) NOT NULL, description TEXT, created_at DATETIME NOT NULL, FOREIGN KEY(client_id) REFERENCES clients(id), tenant_account_id BIGINT UNSIGNED NULL, KEY idx_saas_projects (tenant_account_id,id)) ENGINE=InnoDB;
CREATE TABLE contracts (id INT AUTO_INCREMENT PRIMARY KEY, client_id INT NOT NULL, name VARCHAR(190) NOT NULL, amount_cents BIGINT NOT NULL, starts_on DATE NOT NULL, ends_on DATE NULL, interval_months INT NOT NULL DEFAULT 1, due_day INT NOT NULL DEFAULT 10, status VARCHAR(20) NOT NULL DEFAULT 'active', carryover TINYINT NOT NULL DEFAULT 0, revisions INT NOT NULL DEFAULT 2, auto_bill TINYINT NOT NULL DEFAULT 1, terms TEXT, created_at DATETIME NOT NULL, FOREIGN KEY(client_id) REFERENCES clients(id), tenant_account_id BIGINT UNSIGNED NULL, KEY idx_saas_contracts (tenant_account_id,id)) ENGINE=InnoDB;
CREATE TABLE contract_items (id INT AUTO_INCREMENT PRIMARY KEY, contract_id INT NOT NULL, category_id INT NOT NULL, unit VARCHAR(30) NOT NULL DEFAULT 'unidade', quantity DECIMAL(10,2) NOT NULL, extra_cents BIGINT NOT NULL DEFAULT 0, FOREIGN KEY(contract_id) REFERENCES contracts(id), FOREIGN KEY(category_id) REFERENCES categories(id)) ENGINE=InnoDB;
CREATE TABLE cycles (id INT AUTO_INCREMENT PRIMARY KEY, contract_id INT NOT NULL, starts_on DATE NOT NULL, ends_on DATE NOT NULL, amount_cents BIGINT NOT NULL, UNIQUE KEY contract_cycle(contract_id,starts_on), FOREIGN KEY(contract_id) REFERENCES contracts(id)) ENGINE=InnoDB;
CREATE TABLE cycle_items (id INT AUTO_INCREMENT PRIMARY KEY, cycle_id INT NOT NULL, category_id INT NOT NULL, unit VARCHAR(30) NOT NULL, quantity DECIMAL(10,2) NOT NULL, carried DECIMAL(10,2) NOT NULL DEFAULT 0, extra_cents BIGINT NOT NULL DEFAULT 0, FOREIGN KEY(cycle_id) REFERENCES cycles(id), FOREIGN KEY(category_id) REFERENCES categories(id)) ENGINE=InnoDB;
CREATE TABLE demands (id INT AUTO_INCREMENT PRIMARY KEY, client_id INT NOT NULL, project_id INT NULL, category_id INT NOT NULL, stage_id INT NOT NULL DEFAULT 1, title VARCHAR(190) NOT NULL, brief TEXT NOT NULL, details_json LONGTEXT NOT NULL, due_at DATETIME NOT NULL, priority VARCHAR(20) NOT NULL DEFAULT 'normal', assigned_to INT NULL, whatsapp_recipient_mode VARCHAR(20) NOT NULL DEFAULT 'none', whatsapp_custom_phone VARCHAR(20) NULL, estimated_minutes INT NOT NULL DEFAULT 0, billing_mode VARCHAR(20) NOT NULL DEFAULT 'one_off', amount_cents BIGINT NOT NULL DEFAULT 0, commercial_status VARCHAR(20) NOT NULL DEFAULT 'pending', blocked_reason TEXT, internal_notes TEXT, revisions_limit INT NOT NULL DEFAULT 2, draft TINYINT NOT NULL DEFAULT 0, sort_order INT NOT NULL DEFAULT 0, version INT NOT NULL DEFAULT 1, accepted_at DATETIME NULL, completed_at DATETIME NULL, first_completed_at DATETIME NULL, created_by INT NOT NULL, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, deleted_at DATETIME NULL, drive_folder_id VARCHAR(255) NULL, INDEX(client_id), INDEX(due_at), INDEX(stage_id), KEY idx_demands_ops (deleted_at,stage_id,client_id,category_id,assigned_to,due_at), FOREIGN KEY(client_id) REFERENCES clients(id), FOREIGN KEY(project_id) REFERENCES projects(id), FOREIGN KEY(category_id) REFERENCES categories(id), FOREIGN KEY(stage_id) REFERENCES stages(id), FOREIGN KEY(assigned_to) REFERENCES users(id), FOREIGN KEY(created_by) REFERENCES users(id), tenant_account_id BIGINT UNSIGNED NULL, KEY idx_saas_demands (tenant_account_id,id)) ENGINE=InnoDB;
CREATE TABLE demand_usage (id INT AUTO_INCREMENT PRIMARY KEY, demand_id INT NOT NULL UNIQUE, cycle_item_id INT NOT NULL, quantity DECIMAL(10,2) NOT NULL, state VARCHAR(20) NOT NULL DEFAULT 'reserved', FOREIGN KEY(demand_id) REFERENCES demands(id), FOREIGN KEY(cycle_item_id) REFERENCES cycle_items(id)) ENGINE=InnoDB;
CREATE TABLE transitions (id INT AUTO_INCREMENT PRIMARY KEY, demand_id INT NOT NULL, from_stage INT NULL, to_stage INT NOT NULL, actor_id INT NOT NULL, happened_at DATETIME NOT NULL, FOREIGN KEY(demand_id) REFERENCES demands(id), INDEX(demand_id,happened_at)) ENGINE=InnoDB;
CREATE TABLE comments (id INT AUTO_INCREMENT PRIMARY KEY, demand_id INT NOT NULL, author_id INT NOT NULL, body TEXT NOT NULL, internal TINYINT NOT NULL DEFAULT 0, version_id INT NULL, created_at DATETIME NOT NULL, FOREIGN KEY(demand_id) REFERENCES demands(id), FOREIGN KEY(author_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE checklists (id INT AUTO_INCREMENT PRIMARY KEY, demand_id INT NOT NULL, label VARCHAR(255) NOT NULL, done TINYINT NOT NULL DEFAULT 0, FOREIGN KEY(demand_id) REFERENCES demands(id)) ENGINE=InnoDB;
CREATE TABLE time_entries (id INT AUTO_INCREMENT PRIMARY KEY, demand_id INT NOT NULL, user_id INT NOT NULL, minutes INT NOT NULL, description VARCHAR(255) NOT NULL DEFAULT '', worked_on DATE NOT NULL, created_at DATETIME NOT NULL, FOREIGN KEY(demand_id) REFERENCES demands(id), FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE files (id INT AUTO_INCREMENT PRIMARY KEY, demand_id INT NOT NULL, author_id INT NOT NULL, label VARCHAR(255) NOT NULL, original_name VARCHAR(255) NOT NULL DEFAULT '', disk_name VARCHAR(100) NULL, storage_provider VARCHAR(20) NOT NULL DEFAULT 'local', drive_file_id VARCHAR(255) NULL, drive_account_id INT NULL, drive_web_view_url TEXT NULL, url TEXT NULL, mime VARCHAR(120) NOT NULL DEFAULT '', size_bytes BIGINT NOT NULL DEFAULT 0, upload_key CHAR(64) NULL, shared TINYINT NOT NULL DEFAULT 1, kind VARCHAR(20) NOT NULL DEFAULT 'input', version_no INT NULL, approval VARCHAR(20) NOT NULL DEFAULT 'pending', approved_by INT NULL, approved_at DATETIME NULL, created_at DATETIME NOT NULL, FOREIGN KEY(demand_id) REFERENCES demands(id), FOREIGN KEY(author_id) REFERENCES users(id), UNIQUE KEY demand_version(demand_id,version_no), UNIQUE KEY uq_files_upload_key(upload_key)) ENGINE=InnoDB;
CREATE TABLE reviews (id INT AUTO_INCREMENT PRIMARY KEY, file_id INT NOT NULL, user_id INT NOT NULL, decision VARCHAR(20) NOT NULL, message TEXT, created_at DATETIME NOT NULL, FOREIGN KEY(file_id) REFERENCES files(id), FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE change_requests (id INT AUTO_INCREMENT PRIMARY KEY, demand_id INT NOT NULL, user_id INT NOT NULL, description TEXT NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'pending', response TEXT, created_at DATETIME NOT NULL, FOREIGN KEY(demand_id) REFERENCES demands(id)) ENGINE=InnoDB;
CREATE TABLE invoices (id INT AUTO_INCREMENT PRIMARY KEY, client_id INT NOT NULL, demand_id INT NULL, project_id INT NULL, cycle_id INT NULL, description VARCHAR(255) NOT NULL, amount_cents BIGINT NOT NULL, due_on DATE NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'open', source_key VARCHAR(120) NULL UNIQUE, deleted_at DATETIME NULL, deleted_by INT NULL, delete_reason VARCHAR(500) NULL, created_at DATETIME NOT NULL, KEY idx_invoices_deleted_at (deleted_at), KEY idx_invoices_ops (deleted_at,client_id,due_on,status), FOREIGN KEY(client_id) REFERENCES clients(id), FOREIGN KEY(demand_id) REFERENCES demands(id), FOREIGN KEY(project_id) REFERENCES projects(id), FOREIGN KEY(cycle_id) REFERENCES cycles(id), FOREIGN KEY(deleted_by) REFERENCES users(id), tenant_account_id BIGINT UNSIGNED NULL, KEY idx_saas_invoices (tenant_account_id,id)) ENGINE=InnoDB;
CREATE TABLE payments (id INT AUTO_INCREMENT PRIMARY KEY, invoice_id INT NOT NULL, amount_cents BIGINT NOT NULL, discount_cents BIGINT NOT NULL DEFAULT 0, discount_type VARCHAR(10) NULL, discount_percent DECIMAL(7,4) NULL, paid_on DATE NOT NULL, method VARCHAR(50) NOT NULL, note TEXT, refund_of INT NULL, created_by INT NOT NULL, created_at DATETIME NOT NULL, KEY idx_payments_invoice_settlement(invoice_id,paid_on), FOREIGN KEY(invoice_id) REFERENCES invoices(id), FOREIGN KEY(refund_of) REFERENCES payments(id)) ENGINE=InnoDB;
CREATE TABLE costs (id INT AUTO_INCREMENT PRIMARY KEY, demand_id INT NOT NULL, description VARCHAR(190) NOT NULL, amount_cents BIGINT NOT NULL, spent_on DATE NOT NULL, payment_status VARCHAR(20) NOT NULL DEFAULT 'paid', paid_on DATE NULL, created_at DATETIME NOT NULL, KEY idx_costs_payment (payment_status,paid_on,spent_on), FOREIGN KEY(demand_id) REFERENCES demands(id)) ENGINE=InnoDB;
CREATE TABLE google_accounts (id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NOT NULL, google_sub VARCHAR(190) NOT NULL, email VARCHAR(190) NOT NULL, access_token TEXT NOT NULL, refresh_token TEXT NOT NULL, scopes TEXT NULL, expires_at DATETIME NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'connected', calendar_enabled TINYINT NOT NULL DEFAULT 0, drive_enabled TINYINT NOT NULL DEFAULT 0, last_error TEXT, UNIQUE KEY user_google(user_id,google_sub), FOREIGN KEY(user_id) REFERENCES users(id), tenant_account_id BIGINT UNSIGNED NULL, KEY idx_saas_google_accounts (tenant_account_id,id)) ENGINE=InnoDB;
CREATE TABLE calendars (id INT AUTO_INCREMENT PRIMARY KEY, account_id INT NULL, google_id VARCHAR(255) NULL, name VARCHAR(190) NOT NULL, color VARCHAR(7) NOT NULL DEFAULT '#737373', access_role VARCHAR(40) NOT NULL DEFAULT 'owner', selected TINYINT NOT NULL DEFAULT 1, write_enabled TINYINT NOT NULL DEFAULT 1, sync_token TEXT NULL, synced_at DATETIME NULL, last_error TEXT, channel_id VARCHAR(100) NULL, channel_token VARCHAR(100) NULL, channel_resource VARCHAR(255) NULL, channel_expires DATETIME NULL, dirty TINYINT NOT NULL DEFAULT 1, UNIQUE KEY account_calendar(account_id,google_id), FOREIGN KEY(account_id) REFERENCES google_accounts(id), tenant_account_id BIGINT UNSIGNED NULL, KEY idx_saas_calendars (tenant_account_id,id)) ENGINE=InnoDB;
CREATE TABLE events (id INT AUTO_INCREMENT PRIMARY KEY, calendar_id INT NOT NULL, demand_id INT NULL, title VARCHAR(255) NOT NULL, starts_at DATETIME NOT NULL, ends_at DATETIME NOT NULL, all_day TINYINT NOT NULL DEFAULT 0, location TEXT, description TEXT, organizer_name VARCHAR(190) NULL, organizer_email VARCHAR(190) NULL, attendees_json LONGTEXT NULL, meet_url TEXT NULL, conference_json LONGTEXT NULL, event_url TEXT NULL, attachments_json LONGTEXT NULL, private TINYINT NOT NULL DEFAULT 0, buffer_minutes INT NOT NULL DEFAULT 0, status VARCHAR(20) NOT NULL DEFAULT 'confirmed', origin VARCHAR(20) NOT NULL DEFAULT 'local', google_id VARCHAR(255) NULL, google_etag VARCHAR(255) NULL, recurring_id VARCHAR(255) NULL, sync_status VARCHAR(20) NOT NULL DEFAULT 'local', sync_error TEXT, remote_json LONGTEXT NULL, version INT NOT NULL DEFAULT 1, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, UNIQUE KEY cal_event(calendar_id,google_id), INDEX(starts_at,ends_at), KEY idx_events_calendar_time (calendar_id,starts_at,status), FOREIGN KEY(calendar_id) REFERENCES calendars(id), FOREIGN KEY(demand_id) REFERENCES demands(id)) ENGINE=InnoDB;
CREATE TABLE audit_log (id BIGINT AUTO_INCREMENT PRIMARY KEY, user_id INT NULL, entity VARCHAR(40) NOT NULL, entity_id INT NOT NULL, action VARCHAR(80) NOT NULL, before_json LONGTEXT NULL, after_json LONGTEXT NULL, origin VARCHAR(20) NOT NULL, created_at DATETIME NOT NULL, INDEX(entity,entity_id), KEY idx_audit_entity (entity,entity_id,created_at)) ENGINE=InnoDB;
CREATE TABLE notifications (id BIGINT AUTO_INCREMENT PRIMARY KEY, user_id INT NOT NULL, title VARCHAR(190) NOT NULL, body TEXT NOT NULL, demand_id INT NULL, seen TINYINT NOT NULL DEFAULT 0, dedupe_key VARCHAR(190) NULL UNIQUE, created_at DATETIME NOT NULL, KEY idx_notifications_user (user_id,seen,created_at), FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE chat_threads (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY, user_low_id INT NOT NULL, user_high_id INT NOT NULL, last_message_id BIGINT UNSIGNED NULL, created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL, UNIQUE KEY uq_chat_thread_pair(user_low_id,user_high_id), KEY idx_chat_thread_low_updated(user_low_id,updated_at,id), KEY idx_chat_thread_high_updated(user_high_id,updated_at,id), FOREIGN KEY(user_low_id) REFERENCES users(id), FOREIGN KEY(user_high_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE chat_messages (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY, thread_id BIGINT UNSIGNED NOT NULL, sender_id INT NOT NULL, recipient_id INT NOT NULL, client_nonce CHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, body TEXT NOT NULL, created_at DATETIME(6) NOT NULL, read_at DATETIME(6) NULL, UNIQUE KEY uq_chat_sender_nonce(sender_id,client_nonce), KEY idx_chat_thread_messages(thread_id,id), KEY idx_chat_recipient_unread(recipient_id,read_at,id), KEY idx_chat_sender_recipient(sender_id,recipient_id,id), FOREIGN KEY(thread_id) REFERENCES chat_threads(id), FOREIGN KEY(sender_id) REFERENCES users(id), FOREIGN KEY(recipient_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE chat_message_tasks (message_id BIGINT UNSIGNED NOT NULL, demand_id INT NOT NULL, label VARCHAR(255) NOT NULL, created_at DATETIME(6) NOT NULL, PRIMARY KEY(message_id,demand_id), KEY idx_chat_message_tasks_demand(demand_id,message_id), FOREIGN KEY(message_id) REFERENCES chat_messages(id) ON DELETE CASCADE, FOREIGN KEY(demand_id) REFERENCES demands(id)) ENGINE=InnoDB;

CREATE TABLE automations (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, name VARCHAR(190) NOT NULL, trigger_event VARCHAR(100) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, definition_json JSON NOT NULL, active TINYINT NOT NULL DEFAULT 0, version INT UNSIGNED NOT NULL DEFAULT 1, created_by INT NOT NULL, created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL, PRIMARY KEY(id), KEY idx_automations_active_trigger(active,trigger_event,id), FOREIGN KEY(created_by) REFERENCES users(id), tenant_account_id BIGINT UNSIGNED NULL, KEY idx_saas_automations (tenant_account_id,id)) ENGINE=InnoDB;
CREATE TABLE automation_runs (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, automation_id BIGINT UNSIGNED NOT NULL, operation_id CHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, trigger_event VARCHAR(100) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, entity_type VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, entity_id BIGINT UNSIGNED NOT NULL, status VARCHAR(20) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT 'pending', context_json JSON NOT NULL, attempts INT UNSIGNED NOT NULL DEFAULT 0, available_at DATETIME(6) NOT NULL, started_at DATETIME(6) NULL, finished_at DATETIME(6) NULL, last_error VARCHAR(190) NULL, created_at DATETIME(6) NOT NULL, PRIMARY KEY(id), UNIQUE KEY uq_automation_run_operation(automation_id,operation_id), KEY idx_automation_runs_ready(status,available_at,id), KEY idx_automation_runs_entity(entity_type,entity_id,id), FOREIGN KEY(automation_id) REFERENCES automations(id)) ENGINE=InnoDB;
CREATE TABLE automation_run_steps (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, run_id BIGINT UNSIGNED NOT NULL, node_id VARCHAR(100) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, node_type VARCHAR(50) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, status VARCHAR(20) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, input_json JSON NOT NULL, output_json JSON NULL, attempts INT UNSIGNED NOT NULL DEFAULT 1, started_at DATETIME(6) NOT NULL, finished_at DATETIME(6) NULL, last_error VARCHAR(190) NULL, PRIMARY KEY(id), UNIQUE KEY uq_automation_run_step(run_id,node_id), KEY idx_automation_steps_run(run_id,id), FOREIGN KEY(run_id) REFERENCES automation_runs(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE automation_worker_state (id TINYINT UNSIGNED NOT NULL, last_outbox_id BIGINT UNSIGNED NOT NULL DEFAULT 0, heartbeat_at DATETIME(6) NULL, updated_at DATETIME(6) NOT NULL, PRIMARY KEY(id)) ENGINE=InnoDB;
CREATE TABLE whatsapp_messages (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, run_id BIGINT UNSIGNED NULL, demand_id INT NULL, node_id VARCHAR(100) CHARACTER SET ascii COLLATE ascii_bin NULL, recipient_type VARCHAR(20) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, recipient_user_id INT NULL, recipient_client_id INT NULL, recipient_phone VARCHAR(96) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, body TEXT NOT NULL, status VARCHAR(20) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT 'pending', provider_message_id VARCHAR(255) NULL, attempts INT UNSIGNED NOT NULL DEFAULT 0, last_error VARCHAR(190) NULL, created_at DATETIME(6) NOT NULL, sent_at DATETIME(6) NULL, PRIMARY KEY(id), UNIQUE KEY uq_whatsapp_run_node(run_id,node_id), KEY idx_whatsapp_status_created(status,created_at,id), KEY idx_whatsapp_demand(demand_id,id), FOREIGN KEY(run_id) REFERENCES automation_runs(id) ON DELETE SET NULL, FOREIGN KEY(demand_id) REFERENCES demands(id) ON DELETE SET NULL, FOREIGN KEY(recipient_user_id) REFERENCES users(id) ON DELETE SET NULL, FOREIGN KEY(recipient_client_id) REFERENCES clients(id) ON DELETE SET NULL) ENGINE=InnoDB;
INSERT INTO automation_worker_state (id,last_outbox_id,heartbeat_at,updated_at) SELECT 1,COALESCE(MAX(id),0),NULL,NOW(6) FROM event_outbox WHERE 1=1 ON DUPLICATE KEY UPDATE id=id;
CREATE TABLE ai_whatsapp_inbox (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, session_name VARCHAR(80) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, provider_message_id VARCHAR(255) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, chat_id VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, sender_id VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, auth_user_id INT NULL, chat_type VARCHAR(10) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, message_type VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, body TEXT NULL, status VARCHAR(20) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT 'received', auth_status VARCHAR(20) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT 'pending', auth_reason VARCHAR(50) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT 'pending', auth_checked_at DATETIME(6) NULL, ai_state VARCHAR(20) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT 'ignored', ai_mentions_json TEXT NULL, ai_reply TEXT NULL, ai_error VARCHAR(160) NULL, ai_attempts INT UNSIGNED NOT NULL DEFAULT 0, ai_available_at DATETIME(6) NULL, ai_updated_at DATETIME(6) NULL, ai_processed_at DATETIME(6) NULL, ai_sent_at DATETIME(6) NULL, received_at DATETIME(6) NOT NULL, PRIMARY KEY(id), UNIQUE KEY uq_ai_inbox_provider(session_name,provider_message_id), KEY idx_ai_inbox_pending(status,received_at,id), KEY idx_ai_inbox_chat(session_name,chat_id,id), KEY idx_ai_inbox_sender(sender_id,id), KEY idx_ai_inbox_auth(auth_status,received_at,id), KEY idx_ai_inbox_auth_user(auth_user_id,id), KEY idx_ai_inbox_work(ai_state,ai_available_at,id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
CREATE TABLE mail_queue (id BIGINT AUTO_INCREMENT PRIMARY KEY, recipient VARCHAR(190) NOT NULL, subject VARCHAR(190) NOT NULL, body LONGTEXT NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'pending', sent_at DATETIME NULL, attempts INT NOT NULL DEFAULT 0, last_attempt_at DATETIME NULL, error TEXT, next_attempt DATETIME NOT NULL, created_at DATETIME NOT NULL, KEY idx_mail_queue_status_next (status,next_attempt)) ENGINE=InnoDB;
CREATE TABLE push_subscriptions (id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY, user_id INT NOT NULL, endpoint TEXT NOT NULL, endpoint_hash CHAR(64) NOT NULL, p256dh TEXT NULL, auth_key TEXT NULL, user_agent VARCHAR(255) NULL, active TINYINT NOT NULL DEFAULT 1, last_error TEXT NULL, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, UNIQUE KEY uq_push_endpoint_hash (endpoint_hash), KEY idx_push_user_active (user_id,active), FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE push_delivery_log (id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY, user_id INT NOT NULL, subscription_id BIGINT NULL, notification_id BIGINT NULL, demand_id INT NULL, scope VARCHAR(40) NOT NULL DEFAULT 'task_responsible', title VARCHAR(190) NOT NULL, body TEXT NOT NULL, url TEXT NULL, status VARCHAR(30) NOT NULL, http_code INT NULL, error TEXT NULL, user_agent VARCHAR(255) NULL, created_at DATETIME NOT NULL, KEY idx_push_delivery_created(created_at), KEY idx_push_delivery_user(user_id,created_at), KEY idx_push_delivery_status(status,created_at), KEY idx_push_delivery_demand(demand_id,created_at), FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(subscription_id) REFERENCES push_subscriptions(id), FOREIGN KEY(notification_id) REFERENCES notifications(id), FOREIGN KEY(demand_id) REFERENCES demands(id)) ENGINE=InnoDB;
CREATE TABLE system_errors (id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY, user_id INT NULL, level VARCHAR(20) NOT NULL DEFAULT 'error', context VARCHAR(100) NOT NULL DEFAULT 'app', message TEXT NOT NULL, request_uri TEXT NULL, details_json LONGTEXT NULL, resolved_at DATETIME NULL, created_at DATETIME NOT NULL, KEY idx_system_errors_created (created_at), KEY idx_system_errors_open (resolved_at,created_at), FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE expense_categories (id INT NOT NULL AUTO_INCREMENT PRIMARY KEY, name VARCHAR(80) NOT NULL, active TINYINT NOT NULL DEFAULT 1, created_by INT NULL, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, UNIQUE KEY uq_expense_categories_name(name), KEY idx_expense_categories_active(active,name), tenant_account_id BIGINT UNSIGNED NULL, KEY idx_saas_expense_categories (tenant_account_id,id)) ENGINE=InnoDB;
INSERT INTO expense_categories (name,active,created_at,updated_at) VALUES ('Água',1,NOW(),NOW()),('Energia / Luz',1,NOW(),NOW()),('Internet / Telefonia',1,NOW(),NOW()),('Aluguel',1,NOW(),NOW()),('Software',1,NOW(),NOW()),('Armazenamento / Cloud',1,NOW(),NOW()),('Assinaturas',1,NOW(),NOW()),('Marketing',1,NOW(),NOW()),('Transporte',1,NOW(),NOW()),('Equipamentos',1,NOW(),NOW()),('Impostos',1,NOW(),NOW()),('Serviços',1,NOW(),NOW()),('Alimentação',1,NOW(),NOW()),('Custo Pessoal',1,NOW(),NOW()),('Outros',1,NOW(),NOW());
CREATE TABLE expense_rules (id INT NOT NULL AUTO_INCREMENT PRIMARY KEY, name VARCHAR(190) NOT NULL, vendor VARCHAR(190) NOT NULL DEFAULT '', category VARCHAR(80) NOT NULL DEFAULT 'Outros', amount_cents BIGINT NOT NULL, recurrence VARCHAR(20) NOT NULL DEFAULT 'monthly', starts_on DATE NOT NULL, ends_on DATE NULL, active TINYINT NOT NULL DEFAULT 1, notes TEXT NULL, created_by INT NOT NULL, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, KEY idx_expense_rules_active (active,recurrence,starts_on), FOREIGN KEY(created_by) REFERENCES users(id), tenant_account_id BIGINT UNSIGNED NULL, KEY idx_saas_expense_rules (tenant_account_id,id)) ENGINE=InnoDB;
CREATE TABLE expenses (id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY, rule_id INT NULL, description VARCHAR(190) NOT NULL, vendor VARCHAR(190) NOT NULL DEFAULT '', category VARCHAR(80) NOT NULL DEFAULT 'Outros', amount_cents BIGINT NOT NULL, spent_on DATE NOT NULL, payment_status VARCHAR(20) NOT NULL DEFAULT 'pending', paid_on DATE NULL, notes TEXT NULL, source_key VARCHAR(160) NULL, created_by INT NOT NULL, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, deleted_at DATETIME NULL, UNIQUE KEY uq_expenses_source (source_key), KEY idx_expenses_period (deleted_at,spent_on,category), KEY idx_expenses_payment (payment_status,paid_on,spent_on), KEY idx_expenses_rule (rule_id,spent_on), FOREIGN KEY(rule_id) REFERENCES expense_rules(id), FOREIGN KEY(created_by) REFERENCES users(id), tenant_account_id BIGINT UNSIGNED NULL, KEY idx_saas_expenses (tenant_account_id,id)) ENGINE=InnoDB;
CREATE TABLE whatsapp_contacts (
 id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
 name VARCHAR(190) NOT NULL,
 phone VARCHAR(20) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
 created_by INT NULL,
 created_at DATETIME NOT NULL,
 updated_at DATETIME NOT NULL,
 PRIMARY KEY (id),
 UNIQUE KEY uq_whatsapp_contacts_phone (phone),
 KEY idx_whatsapp_contacts_name (name),
 CONSTRAINT fk_whatsapp_contacts_creator FOREIGN KEY (created_by) REFERENCES users(id) ON DELETE SET NULL,
 tenant_account_id BIGINT UNSIGNED NULL,
 KEY idx_saas_whatsapp_contacts (tenant_account_id,id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
CREATE TABLE reset_tokens (token_hash VARCHAR(64) PRIMARY KEY, user_id INT NOT NULL, expires_at DATETIME NOT NULL, FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE rate_limits (bucket VARCHAR(100) PRIMARY KEY, attempts INT NOT NULL, expires_at DATETIME NOT NULL) ENGINE=InnoDB;
CREATE TABLE api_tokens (id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NOT NULL, name VARCHAR(190) NOT NULL, token_hash VARCHAR(64) NOT NULL UNIQUE, scopes VARCHAR(255) NOT NULL, client_id VARCHAR(100) NULL, refresh_hash VARCHAR(64) NULL UNIQUE, expires_at DATETIME NOT NULL, refresh_expires_at DATETIME NULL, revoked TINYINT NOT NULL DEFAULT 0, created_at DATETIME NOT NULL, FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE oauth_clients (client_id VARCHAR(100) PRIMARY KEY, name VARCHAR(190) NOT NULL, redirect_uris TEXT NOT NULL, created_at DATETIME NOT NULL) ENGINE=InnoDB;
CREATE TABLE oauth_codes (code_hash VARCHAR(64) PRIMARY KEY, user_id INT NOT NULL, client_id VARCHAR(100) NOT NULL, redirect_uri TEXT NOT NULL, challenge VARCHAR(128) NOT NULL, scopes VARCHAR(255) NOT NULL, resource TEXT NOT NULL, expires_at DATETIME NOT NULL) ENGINE=InnoDB;
CREATE TABLE idempotency (user_id INT NOT NULL, operation_key VARCHAR(128) NOT NULL, request_hash VARCHAR(64) NOT NULL, result_json LONGTEXT NULL, created_at DATETIME NOT NULL, PRIMARY KEY(user_id,operation_key)) ENGINE=InnoDB;
CREATE TABLE templates (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(190) NOT NULL, category_id INT NOT NULL, brief TEXT NOT NULL, details_json LONGTEXT NOT NULL, checklist_json TEXT NOT NULL, recurring_client_id INT NULL, next_on DATE NULL, interval_days INT NOT NULL DEFAULT 7, active TINYINT NOT NULL DEFAULT 1, tenant_account_id BIGINT UNSIGNED NULL, KEY idx_saas_templates (tenant_account_id,id)) ENGINE=InnoDB;
